import functools
import inspect
from typing import ForwardRef, Any, Dict, Callable
from fastapi.dependencies.utils import get_typed_signature, get_typed_annotation

def get_typed_annotation(annotation: Any, globalns: Dict[str, Any]) -> Any:
    if isinstance(annotation, str):
        annotation = ForwardRef(annotation)
        # Mocking evaluate_forwardref for simplicity or using the real one if available
        # In the real code it's pydantic.typing.evaluate_forwardref
        # For this test, we can just try to eval it
        try:
            return eval(annotation.__forward_code__, globalns, globalns)
        except Exception as e:
            print(f"Error evaluating forward ref: {e}")
            raise e
    return annotation

def get_typed_signature_mock(call: Callable[..., Any]) -> inspect.Signature:
    signature = inspect.signature(call)
    globalns = getattr(call, "__globals__", {})
    typed_params = [
        inspect.Parameter(
            name=param.name,
            kind=param.kind,
            default=param.default,
            annotation=get_typed_annotation(param.annotation, globalns),
        )
        for param in signature.parameters.values()
    ]
    typed_signature = inspect.Signature(typed_params)
    return typed_signature

